import re, json
G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    name,h,w=m.group(1),int(m.group(2)),int(m.group(3))
    rows=[]
    idx=m.end()
    for line in t[idx:].split('\n'):
        cells=line.split()
        if len(cells)==w and all(c.isdigit() for c in cells):
            rows.append([int(c) for c in cells])
            if len(rows)==h: break
    if len(rows)==h: G[name]=rows
