def phases(g):
    ph={}
    for r,row in enumerate(g):
        for c,v in enumerate(row):
            if v: ph.setdefault((c-r,v),0)
    # collect per color the set of c-r values
    from collections import defaultdict
    d=defaultdict(set); s=defaultdict(set)
    for r,row in enumerate(g):
        for c,v in enumerate(row):
            if v: d[v].add(c-r); s[v].add(r+c)
    return {k:sorted(v) for k,v in d.items()}, {k:sorted(v) for k,v in s.items()}

